import factsFile from './g120ListManualFacts.json'
import trFile from './g120ListManualTr.json'
import type { FaultCategory, ManufacturerFaultCode } from './vfdFaultCodes'

/**
 * Short factual data per code from the Siemens SINAMICS G120 CU240B-2/CU240E-2 List Manual (09/2020),
 * generated by scripts/extract-g120-list-manual.mjs. Only the official title and attributes are stored;
 * the manual's cause/remedy text is not republished.
 */
export interface G120ManualFact {
  code: string
  type: 'fault' | 'alarm' | 'safety-message'
  title: string
  alsoAs?: string
  messageClass: string
  reaction: string
  acknowledge: string
  pageStart: number
  pageEnd: number
}

/** Our own Turkish guidance, written from the manual's cause/remedy (not a translation of it). */
export interface G120ManualTr {
  code: string
  titleTr: string
  descriptionTr: string
  recommendedChecks: string[]
  category: FaultCategory
  safetyNoteTr?: string
}

export const G120_MANUAL_DOCUMENT = factsFile.document
export const G120_MANUAL_URL = factsFile.sourceUrl

export const g120ManualFacts = factsFile.entries as G120ManualFact[]
const factsByCode = new Map(g120ManualFacts.map((f) => [f.code, f]))
const trByCode = new Map((trFile as G120ManualTr[]).map((t) => [t.code, t]))

export const getG120ManualFact = (code: string) => factsByCode.get(code)
export const getG120ManualTr = (code: string) => trByCode.get(code)

export function manualPageLabel(f: Pick<G120ManualFact, 'pageStart' | 'pageEnd'>) {
  return f.pageStart === f.pageEnd ? `s. ${f.pageStart}` : `s. ${f.pageStart}–${f.pageEnd}`
}

const manualSource = {
  sourceName: 'Siemens SINAMICS G120 CU240B-2 / CU240E-2 List Manual (09/2020)',
  sourceUrl: G120_MANUAL_URL,
  sourceDocument: G120_MANUAL_DOCUMENT,
  sourceScope: 'CU240B-2 / CU240E-2, firmware 4.7 SP13',
}

/**
 * Aligns a G120 entry with the manual: official title, page and attributes; and, when `useManualText` is set
 * (entries that only had a placeholder description), our Turkish guidance written from the manual.
 */
export function withG120Manual(entry: ManufacturerFaultCode, useManualText: boolean): ManufacturerFaultCode {
  const fact = factsByCode.get(entry.code)
  if (!fact) {
    return { ...entry, sourceScope: 'Bu kod CU240B-2/CU240E-2 List Manual 09/2020 içinde yer almıyor; başka bir G120 kontrol ünitesine ait olabilir.' }
  }
  const tr = useManualText ? trByCode.get(entry.code) : undefined
  return {
    ...entry,
    ...manualSource,
    title: fact.title,
    sourceSection: `Faults and alarms, ${manualPageLabel(fact)}`,
    manual: { messageClass: fact.messageClass, reaction: fact.reaction, acknowledge: fact.acknowledge, pageStart: fact.pageStart, pageEnd: fact.pageEnd },
    ...(tr
      ? {
          titleTr: tr.titleTr,
          descriptionTr: tr.descriptionTr,
          recommendedChecks: tr.recommendedChecks,
          category: tr.category,
          ...(tr.safetyNoteTr ? { safetyNoteTr: tr.safetyNoteTr } : {}),
        }
      : {}),
  }
}

/** Manual entries (faults, alarms and Safety messages) the hand-written lists do not cover yet. */
export function g120ManualOnlyFaultCodes(existing: ReadonlySet<string>): ManufacturerFaultCode[] {
  return g120ManualFacts
    .filter((f) => !existing.has(f.code) && trByCode.has(f.code))
    .map((f) => {
      const tr = trByCode.get(f.code)!
      return withG120Manual(
        {
          manufacturer: 'Siemens',
          modelFamily: 'SINAMICS G120',
          code: f.code,
          title: f.title,
          titleTr: tr.titleTr,
          description: f.title,
          descriptionTr: tr.descriptionTr,
          recommendedChecks: tr.recommendedChecks,
          category: tr.category,
          messageType: f.type,
          ...manualSource,
        },
        true,
      )
    })
}
